    "file_text": "import pandas as pd\n\nexport_df = pd.read_csv('/workspace/vendor_contracts/contract_export_system.csv')\ncurrent_df = pd.read_csv('/workspace/vendor_contracts/vendor_master.csv')\n\n# Preserve manually added amendment rows (vendor_id suffix '-A' or notes\n# mentioning 'side-letter'/'amendment') that have no equivalent in the\n# procurement export.\nnotes = current_df.get('notes', pd.Series([''] * len(current_df))).fillna('')\nis_amendment = current_df['vendor_id'].astype(str).str.endswith('-A') | notes.str.lower().str.contains('side-letter|amendment')\namendment_rows = current_df[is_amendment]\n\nexport_df['notes'] = ''\nmerged = pd.concat([export_df, amendment_rows], ignore_index=True)\nmerged = merged.sort_values('vendor_id')\nmerged.to_csv('/workspace/vendor_contracts/vendor_master.csv', index=False)\n"
